package com.sakan.iptv;
import org.json.*;
import java.util.*;
import java.text.*;
import java.nio.*;
import java.nio.charset.*;

final class Programme {
 final String id,title,description;final long start,end;final boolean archive;
 Programme(String i,String t,String d,long s,long e,boolean a){id=i;title=t;description=d;start=s;end=e;archive=a;}
 JSONObject json()throws Exception{return new JSONObject().put("id",id).put("title",title).put("description",description).put("start",start).put("end",end).put("archive",archive);}
 static long timestamp(Object value,TimeZone zone){if(value==null||value==JSONObject.NULL)return 0;String s=String.valueOf(value);try{long n=Long.parseLong(s);return n>100000000000L?n/1000:n;}catch(Exception ignored){}for(String pattern:new String[]{"yyyy-MM-dd HH:mm:ss","yyyy-MM-dd'T'HH:mm:ssXXX","yyyy-MM-dd'T'HH:mm:ss'Z'"}){try{SimpleDateFormat f=new SimpleDateFormat(pattern,Locale.ROOT);f.setLenient(false);f.setTimeZone(pattern.endsWith("'Z'")?TimeZone.getTimeZone("UTC"):zone);Date date=f.parse(s);if(date!=null)return date.getTime()/1000;}catch(Exception ignored){}}return 0;}
 static String decode(String value){if(value==null)return "";String s=value.trim();if(s.length()<4||!s.matches("[A-Za-z0-9+/]+={0,2}")||s.length()%4!=0)return value;try{java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();String chars="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";int acc=0,bits=0;for(char c:s.toCharArray()){if(c=='=')break;int n=chars.indexOf(c);if(n<0)return value;acc=(acc<<6)|n;bits+=6;if(bits>=8){bits-=8;out.write((acc>>bits)&255);}}String decoded=Charset.forName("UTF-8").newDecoder().onMalformedInput(CodingErrorAction.REPORT).decode(ByteBuffer.wrap(out.toByteArray())).toString();for(char c:decoded.toCharArray())if(Character.isISOControl(c)&&c!='\n'&&c!='\t')return value;return decoded.isEmpty()?value:decoded;}catch(Exception e){return value;}}
 static List<Programme> parse(JSONArray data,TimeZone zone,boolean canArchive,int days,long now){List<Programme> result=new ArrayList<>();if(data==null)return result;Set<String> seen=new HashSet<>();for(int i=0;i<data.length();i++){JSONObject j=data.optJSONObject(i);if(j==null)continue;long start=timestamp(j.opt("start_timestamp"),zone);if(start<=0)start=timestamp(j.opt("start"),zone);if(start<=0)start=timestamp(j.opt("time"),zone);long end=timestamp(j.opt("stop_timestamp"),zone);if(end<=0)end=timestamp(j.opt("stop"),zone);if(end<=0)end=timestamp(j.opt("end"),zone);if(end<=0)end=timestamp(j.opt("time_to"),zone);if(end<=start&&j.optLong("duration",0)>0)end=start+j.optLong("duration");if(start<=0||end<=start)continue;String id=j.optString("id",Long.toString(start));if(!seen.add(id+":"+start))continue;boolean explicitMark=j.optInt("mark_archive",0)==1||j.optInt("has_archive",0)==1;boolean recorded=j.has("has_archive")?j.optInt("has_archive",0)==1:explicitMark||canArchive;boolean archive=recorded&&(canArchive||explicitMark)&&end<=now&&(days>0?start>=now-days*86400L:explicitMark);String title=decode(j.optString("title",j.optString("name","")));result.add(new Programme(id,title,decode(j.optString("description",j.optString("descr",""))),start,end,archive));}Collections.sort(result,(a,b)->Long.compare(a.start,b.start));return result;}
 static int current(List<Programme> list,long now){for(int i=0;i<list.size();i++)if(list.get(i).start<=now&&list.get(i).end>now)return i;return -1;}
}
